package com.xdownload.mobile;
import android.app.*;import android.app.job.*;import android.content.*;import android.os.*;
/** Persisted, inexact reminder. Never starts a foreground data-sync service from a restricted background context. */
public final class ScheduleService extends JobService{
 static final int JOB=80421,NOTICE=80422;static final String CHANNEL="xdownload.schedule";
 static long next(Store store,long now){long earliest=Long.MAX_VALUE;for(Store.Job j:store.list())if(j.state.equals("scheduled")&&j.notBefore>now)earliest=Math.min(earliest,j.notBefore);return earliest;}
 static int due(Store store,long now){int count=0;for(Store.Job j:store.list())if(j.state.equals("scheduled")&&j.notBefore<=now)count++;return count;}
 static void arm(Context c){try{JobScheduler scheduler=c.getSystemService(JobScheduler.class);if(scheduler==null)return;long now=System.currentTimeMillis(),next=next(Store.get(c),now);if(due(Store.get(c),now)>0)next=now;if(next==Long.MAX_VALUE){scheduler.cancel(JOB);return;}long delay=Math.max(1000,next-now);JobInfo job=new JobInfo.Builder(JOB,new ComponentName(c,ScheduleService.class)).setMinimumLatency(delay).setPersisted(true).build();scheduler.schedule(job);}catch(Exception ignored){}}
 @Override public boolean onStartJob(JobParameters params){Store store=Store.get(this);long now=System.currentTimeMillis();int count=due(store,now);if(count>0){NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel(CHANNEL,"Scheduled downloads",NotificationManager.IMPORTANCE_DEFAULT));if(Build.VERSION.SDK_INT<33||checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==android.content.pm.PackageManager.PERMISSION_GRANTED){PendingIntent open=PendingIntent.getActivity(this,NOTICE,new Intent(this,MainActivity.class).putExtra("resume_due",true).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);nm.notify(NOTICE,new Notification.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.stat_sys_download).setContentTitle("Scheduled downloads ready").setContentText(count+" ready • tap to resume").setContentIntent(open).setAutoCancel(true).build());}}long future=next(store,now);if(future!=Long.MAX_VALUE){JobInfo job=new JobInfo.Builder(JOB,new ComponentName(this,ScheduleService.class)).setMinimumLatency(Math.max(1000,future-now)).setPersisted(true).build();getSystemService(JobScheduler.class).schedule(job);}return false;}
 @Override public boolean onStopJob(JobParameters p){return false;}
}